enum CTCharacterCollection {
  kCTCharacterCollectionIdentityMapping(0),
  kCTCharacterCollectionAdobeCNS1(1),
  kCTCharacterCollectionAdobeGB1(2),
  kCTCharacterCollectionAdobeJapan1(3),
  kCTCharacterCollectionAdobeJapan2(4),
  kCTCharacterCollectionAdobeKorea1(5);

  static const kCTIdentityMappingCharacterCollection =
      kCTCharacterCollectionIdentityMapping;
  static const kCTAdobeCNS1CharacterCollection =
      kCTCharacterCollectionAdobeCNS1;
  static const kCTAdobeGB1CharacterCollection = kCTCharacterCollectionAdobeGB1;
  static const kCTAdobeJapan1CharacterCollection =
      kCTCharacterCollectionAdobeJapan1;
  static const kCTAdobeJapan2CharacterCollection =
      kCTCharacterCollectionAdobeJapan2;
  static const kCTAdobeKorea1CharacterCollection =
      kCTCharacterCollectionAdobeKorea1;

  final int value;
  const CTCharacterCollection(this.value);

  static CTCharacterCollection fromValue(int value) => switch (value) {
    0 => kCTCharacterCollectionIdentityMapping,
    1 => kCTCharacterCollectionAdobeCNS1,
    2 => kCTCharacterCollectionAdobeGB1,
    3 => kCTCharacterCollectionAdobeJapan1,
    4 => kCTCharacterCollectionAdobeJapan2,
    5 => kCTCharacterCollectionAdobeKorea1,
    _ => throw ArgumentError('Unknown value for CTCharacterCollection: $value'),
  };

  @override
  String toString() {
    if (this == kCTCharacterCollectionIdentityMapping)
      return "CTCharacterCollection.kCTCharacterCollectionIdentityMapping, CTCharacterCollection.kCTIdentityMappingCharacterCollection";
    if (this == kCTCharacterCollectionAdobeCNS1)
      return "CTCharacterCollection.kCTCharacterCollectionAdobeCNS1, CTCharacterCollection.kCTAdobeCNS1CharacterCollection";
    if (this == kCTCharacterCollectionAdobeGB1)
      return "CTCharacterCollection.kCTCharacterCollectionAdobeGB1, CTCharacterCollection.kCTAdobeGB1CharacterCollection";
    if (this == kCTCharacterCollectionAdobeJapan1)
      return "CTCharacterCollection.kCTCharacterCollectionAdobeJapan1, CTCharacterCollection.kCTAdobeJapan1CharacterCollection";
    if (this == kCTCharacterCollectionAdobeJapan2)
      return "CTCharacterCollection.kCTCharacterCollectionAdobeJapan2, CTCharacterCollection.kCTAdobeJapan2CharacterCollection";
    if (this == kCTCharacterCollectionAdobeKorea1)
      return "CTCharacterCollection.kCTCharacterCollectionAdobeKorea1, CTCharacterCollection.kCTAdobeKorea1CharacterCollection";
    return super.toString();
  }
}

