enum EvCmd {
  EVNOP(0),
  EVHIDE(1),
  EVSHOW(2),
  EVMOVE(3),
  EVLEVEL(4);

  final int value;
  const EvCmd(this.value);

  static EvCmd fromValue(int value) => switch (value) {
    0 => EVNOP,
    1 => EVHIDE,
    2 => EVSHOW,
    3 => EVMOVE,
    4 => EVLEVEL,
    _ => throw ArgumentError('Unknown value for EvCmd: $value'),
  };
}

