  LAUNCH_DATA_REAL(5),
  LAUNCH_DATA_BOOL(6),
  LAUNCH_DATA_STRING(7),
  LAUNCH_DATA_OPAQUE(8),
  LAUNCH_DATA_ERRNO(9),
  LAUNCH_DATA_MACHPORT(10);

