    8 => LAUNCH_DATA_OPAQUE,
    9 => LAUNCH_DATA_ERRNO,
    10 => LAUNCH_DATA_MACHPORT,
    _ => throw ArgumentError('Unknown value for launch_data_type_t: $value'),
  };
}

