enum virtual_memory_guard_exception_code_t {
  kGUARD_EXC_DEALLOC_GAP(1),
  kGUARD_EXC_RECLAIM_COPYIO_FAILURE(2),
  kGUARD_EXC_RECLAIM_INDEX_FAILURE(4),
  kGUARD_EXC_RECLAIM_DEALLOCATE_FAILURE(8),
  kGUARD_EXC_RECLAIM_ACCOUNTING_FAILURE(9),
  kGUARD_EXC_SEC_IOPL_ON_EXEC_PAGE(10),
  kGUARD_EXC_SEC_EXEC_ON_IOPL_PAGE(11),
  kGUARD_EXC_SEC_UPL_WRITE_ON_EXEC_REGION(12),
  kGUARD_EXC_SEC_ACCESS_FAULT(98),
  kGUARD_EXC_SEC_ASYNC_ACCESS_FAULT(99),
  kGUARD_EXC_SEC_COPY_DENIED(100),
  kGUARD_EXC_SEC_SHARING_DENIED(101);

  final int value;
  const virtual_memory_guard_exception_code_t(this.value);

  static virtual_memory_guard_exception_code_t fromValue(int value) =>
      switch (value) {
        1 => kGUARD_EXC_DEALLOC_GAP,
        2 => kGUARD_EXC_RECLAIM_COPYIO_FAILURE,
        4 => kGUARD_EXC_RECLAIM_INDEX_FAILURE,
        8 => kGUARD_EXC_RECLAIM_DEALLOCATE_FAILURE,
        9 => kGUARD_EXC_RECLAIM_ACCOUNTING_FAILURE,
        10 => kGUARD_EXC_SEC_IOPL_ON_EXEC_PAGE,
        11 => kGUARD_EXC_SEC_EXEC_ON_IOPL_PAGE,
        12 => kGUARD_EXC_SEC_UPL_WRITE_ON_EXEC_REGION,
        98 => kGUARD_EXC_SEC_ACCESS_FAULT,
        99 => kGUARD_EXC_SEC_ASYNC_ACCESS_FAULT,
        100 => kGUARD_EXC_SEC_COPY_DENIED,
        101 => kGUARD_EXC_SEC_SHARING_DENIED,
        _ => throw ArgumentError(
          'Unknown value for virtual_memory_guard_exception_code_t: $value',
        ),
      };
}

